Please create the game logic in the `game_logic.py` file, using the following structure:

```python
class Player:
    def __init__(self):
        self.health = 100
        self.hunger = 50
        self.thirst = 50
        self.resources = {'food': 0, 'water': 0}

class Island:
    def __init__(self):
        self.locations = {
            'beach': {'resources': {'food': 10, 'water': 5}},
            'cave': {'resources': {'food': 20, 'water': 10}}
        }

class Game:
    def __init__(self):
        self.player = Player()
        self.island = Island()

    def game_loop(self):
        while True:
            print("Welcome to Mystery Island!")
            print("Your current resources:")
            print(f"Health: {self.player.health}")
            print(f"Hunger: {self.player.hunger}")

